const input = $input.first().json || {};

const PX = 2625;
const amazonOrderId = input.amazonOrderId || 'ORDER';
const interior = Array.isArray(input.interiorPagesHTML) ? input.interiorPagesHTML : null;
const concatHtml = typeof input.pages_html === 'string' ? input.pages_html : '';
const pageCss = input.page_css || '';

// Build per-page blocks if array missing
function splitPages(html){
  if (!html) return [];
  // Split on each page root div boundary, keep the delimiter
  const parts = html.split(/<div\\s+class=["']book-page["'][^>]*>/i).filter(Boolean);
  // Each part misses the opening div, add it back and close tags
  return parts.map(p => {
    // ensure we include the opening div back
    return `<div class="book-page">${p}`;
  });
}

const blocks = interior && interior.length ? interior
              : splitPages(concatHtml);

