const PNG_OVERRIDE = `
<style id="png-override-final">
  @page { size: ${PX}px ${PX}px; margin: 0; }
  html, body { width:${PX}px; height:${PX}px; margin:0; padding:0; overflow:hidden; }
  .book-page{ width:${PX}px !important; height:${PX}px !important; }
</style>`;

// Wrap a page block into a full HTML doc
function wrapDoc(pageBlock){
  return `<!DOCTYPE html>
<html>
  <head>
    <meta charset="UTF-8">
    ${pageCss || ""}
    ${PNG_OVERRIDE}
  </head>
  <body>
    ${pageBlock}
  </body>
</html>`;
}

