    @font-face { font-family:'CustomBook'; src:url('${backendUrl}/api/assets/${renderCtx.font || 'book-mvp-simple-adventure/fonts/CustomBook.ttf'}') format('truetype'); font-display:swap; }
    .front-title-wrap {
      position:absolute; left:${frontSafeX - 700}px; top:${Math.floor(PX_H*0.18)}px; width:1400px; text-align:center;
      padding: 12px 24px; z-index: 6;
    }
    .title {
