  </style>
</head>
<body>
  <div class="cover-spread">
    <div class="bg"></div>
    <div class="half back"></div>
    <div class="half front"></div>
    <div class="spine"></div>
    <div class="front-title-wrap">
      <div class="title">${title.replace(/&/g,'&amp;').replace(/</g,'&lt;')}</div>
      ${subtitle ? `<div class="subtitle">${subtitle.replace(/&/g,'&amp;').replace(/</g,'&lt;')}</div>` : ''}
    </div>
    <div class="character"><img src="${pose00Url}" alt=""></div>
  </div>
</body>
</html>`;

// Deterministic output
const coverImageFilename = 'cover-spread.png';
const coverImageR2Key = `book-mvp-simple-adventure/orders/${amazonOrderId}/preview-images/${coverImageFilename}`;

// Keep template IDs as-is (hardcoded allowed per instructions)
const pdfMonkeyCoverImageTemplateId = "23277725-4AB0-446A-98C5-CB99C21822B3";

return [{
  json: {
    ...orderCtx,
    backendUrl,
    coverHTML,
    coverImageFilename,
    coverImageR2Key,
    pdfMonkeyCoverImageTemplateId
  }
}];

/**
 * Poll Cover Image (3A) — v2 Code (runOncePerItem)
 * Input: create response from PDFMonkey
 * Output: merges original json + { pdfMonkeyCoverDocumentId, coverImageDownloadUrl }
 */
const createResp = $input.item.json || {};
const doc = createResp.data || createResp.document || createResp;
const docId = doc && (doc.id || doc.data?.id);

if (!docId) {
  throw new Error('PDFMonkey create response missing id (cover)');
}

const http = this.helpers.httpRequest;
const apiBase = 'https://api.pdfmonkey.io/api/v1/documents/';
const headers = { Authorization: 'Bearer 2zpxHdmsse2ECXgVVtVR' };

async function sleep(ms){ return new Promise(r=>setTimeout(r, ms)); }

let status = doc.status || 'queued';
let downloadUrl = doc.download_url || null;
let attempts = 0;

while (attempts < 15) {
  if (status === 'success' && downloadUrl) break;
  const resp = await http({ method: 'GET', url: apiBase + docId, json: true, headers });
  const d = resp.data || resp.document || resp;
  status = d.status;
  downloadUrl = d.download_url || d.file_url || null;
  if (status === 'success' && downloadUrl) break;
  attempts++;
  await sleep(2000);
}

if (status !== 'success' || !downloadUrl) {
  throw new Error(`PDFMonkey cover image not ready after polling (status=${status})`);
}

const input = $input.item.json;
return {
  json: {
    ...input,
    pdfMonkeyCoverDocumentId: docId,
    coverImageDownloadUrl: downloadUrl
  }
};

/**
 * Normalize Inputs (3A Phase 1)
 * - Trims/clamps human text inputs.
 * - Produces a compact `inputs` object for downstream HTML builders.
 * Output: { inputs }
 */
const order = $input.first().json || {};

function s(v){ return (v == null) ? '' : String(v); }
function trim(v){ return s(v).replace(/\s+/g,' ').trim(); }
function clamp(str, max){ const t = s(str); return t.length > max ? t.slice(0, max) : t; }
function safeMultiline(str, max){ 
  let out = s(str).replace(/\r\n/g, '\n').replace(/\r/g, '\n');
  if (out.length > max) out = out.slice(0, max);
  return out;
}

// Source fields
const cs  = order.characterSpecs || {};
const bs  = order.bookSpecs || {};
const od  = order.orderDetails || {};

// Dedication can come from multiple places (prefer orderDetails)
const dedicationRaw = od.dedicationMessage ?? bs.dedicationMessage ?? '';
const hometownRaw   = cs.hometown ?? od.shippingAddress?.city ?? '';

// Title/subtitle
let title    = trim(bs.title || '');
let subtitle = trim(bs.subtitle || '');

// Defaults
if (!title) title = "Alex and the Adventure Compass";

// Core inputs
const inputs = {
  title: clamp(title, 90),
  subtitle: clamp(subtitle, 120),
  dedicationMessage: safeMultiline(dedicationRaw, 400),
  hometown: clamp(hometownRaw, 60),
  childName: clamp(cs.childName || '', 40),
};

return [{ json: { inputs } }];

/**
 * Resolve Asset Paths (3A Phase 1) — HOTFIX
 * Robustly derives orderId/characterHash from multiple upstream nodes,
 * then emits deterministic R2 keys for cover & page assets.
 * Output: { renderContext }
 */
function pick(...vals){ for (const v of vals){ if (v !== undefined && v !== null && v !== '') return v; } return null; }
function tryItems(name){
  try { return $items(name, 0, $runIndex)?.[0]?.json || null; } catch { return null; }
}

const in0 = $input.first()?.json || null;
const fromBuild   = tryItems('Build Assembly Input From Manifest');
const fromReady   = tryItems('Get Order Ready for Assembly');
const fromManHTTP = (()=>{
  const m = tryItems('Download 2B Manifest') || {};
  const o = m.order || {};
  return {
    amazonOrderId: o.amazonOrderId,
    characterHash: m.characterHash || o.characterHash,
    characterSpecs: o.characterSpecs,
    bookSpecs: o.bookSpecs,
    orderDetails: o.orderDetails
  };
})();

// Assemble unified context
const ctx = {
  backendUrl: pick(in0?.backendUrl, tryItems('Extract Manifest URL (3)')?.backendUrl, 'https://admin.littleherolabs.com'),
  amazonOrderId: pick(in0?.amazonOrderId, fromBuild?.amazonOrderId, fromReady?.amazonOrderId, fromManHTTP?.amazonOrderId),
  characterHash: pick(in0?.characterHash, fromBuild?.characterHash, fromReady?.characterHash, fromManHTTP?.characterHash),
};

if (!ctx.amazonOrderId || !ctx.characterHash) {
  const dbg = { have: { in0: !!in0, fromBuild: !!fromBuild, fromReady: !!fromReady, fromManHTTP: !!fromManHTTP },
                fields: { amazonOrderId: ctx.amazonOrderId, characterHash: ctx.characterHash } };
  throw new Error('Resolve Asset Paths: unable to derive orderId/characterHash → ' + JSON.stringify(dbg));
}

// Deterministic R2 keys
const fontKey         = 'book-mvp-simple-adventure/fonts/CustomBook.ttf';
const coversBgKey     = 'book-mvp-simple-adventure/backgrounds/page00-covers.png';
const dedicationBgKey = 'book-mvp-simple-adventure/backgrounds/page00-dedication.png';
const p05OverlayKey   = 'book-mvp-simple-adventure/overlays/pages/page05-overlay.png';
const p12OverlayKey   = 'book-mvp-simple-adventure/overlays/pages/page12-overlay.png';
const pose00Key       = `book-mvp-simple-adventure/order-generated-assets/characters/${ctx.characterHash}/base-character.png`;

const renderContext = {
  font: fontKey,
  coversBg: coversBgKey,
  dedicationBg: dedicationBgKey,
  p05Overlay: p05OverlayKey,
  p12Overlay: p12OverlayKey,
  pose00: pose00Key,
  backendUrl: ctx.backendUrl,
  orderId: ctx.amazonOrderId,
  characterHash: ctx.characterHash
};

return [{ json: { renderContext } }];

/**
 * Load Background Images (pages 1..14)
 * Uses backend proxy URLs for R2 assets. Backgrounds live at:
 *   little-hero-assets/book-mvp-simple-adventure/backgrounds/pageXX-<slug>.png
 */
const order = $input.first().json || {};

// Get backendUrl from context or use default
let backendUrl = order.backendUrl;
if (!backendUrl) {
  try {
    const ctx = $items('Extract Manifest URL (3)', 0, $runIndex)?.[0]?.json || {};
    backendUrl = ctx.backendUrl || 'https://admin.littleherolabs.com';
  } catch {
    backendUrl = 'https://admin.littleherolabs.com';
  }
}

if (!order.amazonOrderId) {
  throw new Error('Amazon Order ID is required for loading background images');
}

// Keep slugs in lockstep with your storage names.
const sceneSlugs = [
  'twilight-walk','night-forest','magic-doorway','courage-leap','morning-meadow',
  'tall-forest','mountain-vista','picnic-surprise','beach-discovery','crystal-cave',
  'giant-flowers','almost-there','animal-reveal','flying-home'
];
const sceneNames = [
  'twilight_walk','night_forest','magic_doorway','courage_leap','morning_meadow',
  'tall_forest','mountain_vista','picnic_surprise','beach_discovery','crystal_cave',
  'giant_flowers','enchanted_grove','animal_reveal','flying_home'
];

// Construct backend proxy URLs for backgrounds
// Prepend page 0 (dedication)
const dedication = {
  pageNumber: 0,
  imagePath: `${backendUrl}/api/assets/book-mvp-simple-adventure/backgrounds/page00-dedication.png`,
  sceneName: 'dedication',
  validated: false,
};

const backgroundImages = [dedication, ...Array.from({ length: 14 }, (_, i) => {
  const pageNumber = i + 1;
  const r2Key = `book-mvp-simple-adventure/backgrounds/page${String(pageNumber).padStart(2,'0')}-${sceneSlugs[i]}.png`;
  const imagePath = `${backendUrl}/api/assets/${r2Key}`;
  return {
    pageNumber,
    imagePath,
    sceneName: sceneNames[i],
    validated: false,
  };
})];

const coverSpreadImagePath = `${backendUrl}/api/assets/book-mvp-simple-adventure/covers/cover-spread.png`;
return [{ json: { ...order, backgroundImages, backendUrl, coverSpreadImagePath } }];

/**
 * QA Gate (3A Phase 4)
 * - Validates the manifest produced by "Build 3A Manifest"
 * - Ensures required pages, sizes, assets, and cover are present
 * - Throws with a JSON summary on failure
 * - On pass, attaches `qa` object and forwards
 */
const input = $input.first().json || {};

// Try to get manifest from current item or upstream
let manifest = input.manifest;
if (!manifest) {
  try { manifest = $items('Build 3A Manifest', 0, $runIndex)?.[0]?.json?.manifest || null; } catch {}
}
if (!manifest) throw new Error('QA Gate: manifest not found');

// Helpers
const asKey = (v) => (typeof v === 'string') ? v : (v && typeof v === 'object' ? (v.key || v.path || v.r2Key || null) : null);
const isObj = (v) => v && typeof v === 'object' && !Array.isArray(v);

// Start checks
const checks = [];
function check(cond, label, meta={}){
  checks.push({label, pass: !!cond, ...meta});
  return !!cond;
}

const schemaOk = typeof manifest.schema === 'string' && manifest.schema.startsWith('lhb.run-manifest@');
check(schemaOk, 'schema present & correct', { schema: manifest.schema });

const sizes = isObj(manifest.pngGeneration) ? manifest.pngGeneration : {};
const sizeInteriorOk = isObj(sizes.sizeInterior) && sizes.sizeInterior.w === 2625 && sizes.sizeInterior.h === 2625;
const sizeCoverOk    = isObj(sizes.sizeCover)    && sizes.sizeCover.w === 5203 && sizes.sizeCover.h === 2625;
check(sizeInteriorOk, 'interior PNG size is 2625×2625', { sizeInterior: sizes.sizeInterior });
check(sizeCoverOk,    'cover PNG size is 5203×2625',    { sizeCover: sizes.sizeCover });

const pages = isObj(manifest.pages) ? manifest.pages : (isObj(sizes.pages) ? sizes.pages : {});

// Expect dedication + 14 story pages
const expectedKeys = ['p00_dedication', ...Array.from({length:14}, (_,i)=> (i+1<10?`p0${i+1}`:`p${i+1}`))];
const missing = [];
const nullish = [];

for (const k of expectedKeys) {
  const entry = pages[k];
  if (entry === undefined) { missing.push(k); continue; }
  const key = asKey(entry);
  if (!key || key === 'null' || key === 'undefined') nullish.push(k);
}
check(missing.length === 0, 'all pages present (p00 + p01..p14)', { missing });
check(nullish.length === 0, 'page keys are non-null', { nullish });

const coverKey = sizes.coverSpreadImage || null;
check(!!coverKey, 'coverSpreadImage present', { coverKey });

const assets = isObj(manifest.assetsUsed) ? manifest.assetsUsed : {};
const fontOk     = !!assets.font;
const coversBgOk = !!assets.coversBg;
const dedicationBgOk = !!assets.dedicationBg;
check(fontOk, 'font asset present', { font: assets.font });
check(coversBgOk, 'coversBg asset present', { coversBg: assets.coversBg });
check(dedicationBgOk, 'dedicationBg asset present', { dedicationBg: assets.dedicationBg });

// p05 overlay is required; p12 optional
const overlays = Array.isArray(assets.overlays) ? assets.overlays : [];
const hasP05 = overlays.some(k => /page05|p05/i.test(String(k)));
check(hasP05, 'p05 overlay declared', { overlays });

// Build summary
const pass = checks.every(c => c.pass === true);

const summary = {
  pass,
  reasons: checks.filter(c => !c.pass).map(c => c.label),
  checks,
  expectedCount: expectedKeys.length,
  missing,
  nullish,
  coverKey,
};

if (!pass) {
  // Throw a compact error—keep details in message as JSON for debug
  throw new Error('QA Gate failed: ' + JSON.stringify(summary));
}

// On success, attach qa summary
return [{
  json: {
    ...input,
    qa: summary
  }
}];

/**
 * Acceptance Tests (3A Phase 5)
 * - Compiles a Markdown report and a machine-readable verdict
 * - Reads manifest from "Build 3A Manifest" and page images from "Collect Page Preview Images"
 */
// Gather upstream artifacts
let manifest = null;
let collector = null;
let qa = null;
try { manifest  = $items('Build 3A Manifest', 0, $runIndex)?.[0]?.json?.manifest || null; } catch {}
try { collector = $items('Collect Page Preview Images', 0, $runIndex)?.[0]?.json || null; } catch {}
try { qa = $items('QA Gate (3A Phase 4)', 0, $runIndex)?.[0]?.json?.qa || null; } catch {}

if (!manifest) throw new Error('Acceptance: manifest not found');

const pages = (manifest.pngGeneration && manifest.pngGeneration.pages) || manifest.pages || {};
const pageKeys = Object.keys(pages || {});
const expectedKeys = ['p00_dedication', ...Array.from({length:14}, (_,i)=> (i+1<10?`p0${i+1}`:`p${i+1}`))];
const missing = expectedKeys.filter(k => !(k in pages));
const coverKey = manifest.pngGeneration?.coverSpreadImage || null;

// Verdict booleans
const sizesOk = manifest.pngGeneration?.sizeInterior?.w === 2625
             && manifest.pngGeneration?.sizeInterior?.h === 2625
             && manifest.pngGeneration?.sizeCover?.w === 5203
             && manifest.pngGeneration?.sizeCover?.h === 2625;

const hasAllPages = missing.length === 0
  && expectedKeys.every(k => {
    const v = pages[k];
    return typeof v === 'string' ? !!v : !!(v && (v.key || v.path || v.r2Key));
  });

const coverOk = !!coverKey;
const qaPass = !!(qa && qa.pass === true);
const collectedCount = Number(collector?.pagePreviewImages?.length || 0);
const matchesCollector = hasAllPages && (collectedCount >= 15); // p00..p14 expected

const verdict = {
  sizesOk,
  hasAllPages,
  coverOk,
  qaPass,
  matchesCollector,
  readyToUploadManifest: sizesOk && hasAllPages && coverOk && qaPass
};

// Markdown report
function badge(ok){ return ok ? '✅' : '❌'; }
const lines = [];
lines.push(`# Workflow 3A — Acceptance Report`);
lines.push(`Generated: ${new Date().toISOString()}`);
lines.push('');
lines.push(`**Order:** ${manifest.amazonOrderId || 'UNKNOWN'}  `);
lines.push(`**Character Hash:** ${manifest.characterHash || 'UNKNOWN'}  `);
lines.push('');
lines.push(`## Summary`);
lines.push(`- Sizes: ${badge(verdict.sizesOk)} interior 2625×2625; cover 5203×2625`);
lines.push(`- Pages present: ${badge(verdict.hasAllPages)} (expected 15 incl. dedication)`);
lines.push(`- Cover image present: ${badge(verdict.coverOk)}`);
lines.push(`- QA Gate: ${badge(verdict.qaPass)}`);
lines.push(`- Collector consistency: ${badge(verdict.matchesCollector)} (pages=${collectedCount})`);
lines.push('');
if (missing.length) {
  lines.push(`**Missing pages:** ${missing.join(', ')}`);
  lines.push('');
}
lines.push('## Assets Used');
const au = manifest.assetsUsed || {};
lines.push(`- Font: \`${au.font || 'n/a'}\``);
lines.push(`- Covers BG: \`${au.coversBg || 'n/a'}\``);
lines.push(`- Dedication BG: \`${au.dedicationBg || 'n/a'}\``);
lines.push(`- Overlays: ${Array.isArray(au.overlays) ? au.overlays.map(k => `\`${k}\``).join(', ') : 'n/a'}`);
lines.push('');
lines.push('## Page Keys');
expectedKeys.forEach(k => {
  const v = pages[k];
  let val = (typeof v === 'string') ? v : (v && (v.key || v.path || v.r2Key) || 'null');
  lines.push(`- ${k}: ${val ? '`' + val + '`' : '`null`'}`);
});

const reportMd = lines.join('\n');

return [{
  json: {
    reportMd,
    verdict,
    manifestSummary: {
      orderId: manifest.amazonOrderId || null,
      characterHash: manifest.characterHash || null,
      coverKey
    }
  }
}];
